if (status === null || status >= 500) return [{json:{ok:false,retry:true,ctx,error:{code:status===null?'NETWORK':'SERVER_ERROR',message:'ticket store unavailable'}}}];
if (![200,201].includes(status)) return [{json:{ok:false,retry:false,ctx,error:{code:b?.error?.code || 'HTTP_ERROR',message:'ticket request rejected'}}}];
